#include <stddef.h>

const char *
find_end_of_line (const char *s, size_t len)
{
  for (const auto end = s + len; s != end; ++s)
    {
      if (*s == '\n')
        return s;
      if (*s == '\r')
        {
          const auto next = s + 1;
          if (next == end)
            {
              break;
            }
          return (*next == '\n' ? next : s);
        }
    }
  return nullptr;
}
